def has_duplicate_slow(nums):
    """O(n^2) time, O(1) space: compare every pair."""
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] == nums[j]:
                return True
    return False


def has_duplicate_fast(nums):
    """O(n) time, O(n) space: remember what we have seen."""
    seen = set()
    for x in nums:
        if x in seen:
            return True
        seen.add(x)
    return False


