def compress(s: str) -> str:
    """'aaabcc' -> 'a3b1c2'"""
    if not s:
        return ""
    parts, count = [], 1
    for prev, ch in zip(s, s[1:]):
        if ch == prev:
            count += 1
        else:
            parts.append(f"{prev}{count}")
            count = 1
    parts.append(f"{s[-1]}{count}")
    return "".join(parts)


