def daily_temperatures(temps):
    answer = [0] * len(temps)
    stack = []                              # indexes with decreasing temps
    for i, t in enumerate(temps):
        while stack and temps[stack[-1]] < t:
            j = stack.pop()
            answer[j] = i - j
        stack.append(i)
    return answer


