from collections import deque


def bfs_shortest(graph, start, goal):
    """Number of edges on the shortest path, or -1."""
    queue, seen = deque([(start, 0)]), {start}
    while queue:
        node, dist = queue.popleft()
        if node == goal:
            return dist
        for nxt in graph.get(node, []):
            if nxt not in seen:
                seen.add(nxt)               # mark on push
                queue.append((nxt, dist + 1))
    return -1


def count_components(graph):
    seen, count = set(), 0

    def dfs(node):
        seen.add(node)
        for nxt in graph[node]:
            if nxt not in seen:
                dfs(nxt)

    for node in graph:
        if node not in seen:
            dfs(node)
            count += 1
    return count


def num_islands(grid):
    rows, cols = len(grid), len(grid[0]) if grid else 0
    seen, islands = set(), 0

    def dfs(r, c):
        if not (0 <= r < rows and 0 <= c < cols) or grid[r][c] != "1" or (r, c) in seen:
            return
        seen.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            dfs(r + dr, c + dc)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "1" and (r, c) not in seen:
                dfs(r, c)
                islands += 1
    return islands


