import math

MOD = 10**9 + 7


def gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def sieve(n):
    is_prime = [True] * (n + 1)
    is_prime[0:2] = [False, False][: min(2, n + 1)]
    for p in range(2, int(n ** 0.5) + 1):
        if is_prime[p]:
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False
    return [i for i, ok in enumerate(is_prime) if ok]


def fast_pow(base, exp, mod):
    result, base = 1, base % mod
    while exp:
        if exp & 1:
            result = result * base % mod
        base = base * base % mod
        exp >>= 1
    return result


def ncr_mod(n, r, mod=MOD):
    if r < 0 or r > n:
        return 0
    num = den = 1
    for i in range(r):
        num = num * (n - i) % mod
        den = den * (i + 1) % mod
    return num * pow(den, mod - 2, mod) % mod       # modular inverse


