from urllib.parse import urlparse, parse_qs


class UserApi:
    """A tiny in-memory API that follows REST rules (framework-free)."""

    def __init__(self):
        self.users, self.next_id = {}, 1

    def handle(self, method, url, body=None):
        parsed = urlparse(url)
        parts = [p for p in parsed.path.split("/") if p]
        query = parse_qs(parsed.query)

        if parts == ["users"]:
            if method == "POST":
                if not body or not body.get("name"):
                    return 400, {"error": "name is required"}
                user = {"id": self.next_id, "name": body["name"]}
                self.users[self.next_id] = user
                self.next_id += 1
                return 201, user
            if method == "GET":
                limit = int(query.get("limit", [10])[0])
                offset = int(query.get("offset", [0])[0])
                items = list(self.users.values())[offset: offset + limit]
                return 200, {"items": items, "total": len(self.users)}
            return 405, {"error": "method not allowed"}

        if len(parts) == 2 and parts[0] == "users" and parts[1].isdigit():
            uid = int(parts[1])
            if uid not in self.users:
                return 404, {"error": "user not found"}
            if method == "GET":
                return 200, self.users[uid]
            if method == "PUT":
                if not body or not body.get("name"):
                    return 400, {"error": "name is required"}
                self.users[uid] = {"id": uid, "name": body["name"]}
                return 200, self.users[uid]
            if method == "DELETE":
                del self.users[uid]
                return 204, None
            return 405, {"error": "method not allowed"}
        return 404, {"error": "route not found"}


