from collections import deque


def round_robin(procs, quantum):
    """procs: list of (name, arrival, burst). Returns completion times."""
    procs = sorted(procs, key=lambda p: p[1])
    remaining = {name: burst for name, _, burst in procs}
    queue, done, time, i = deque(), {}, 0, 0

    def admit(upto):
        nonlocal i
        while i < len(procs) and procs[i][1] <= upto:
            queue.append(procs[i][0])
            i += 1

    admit(0)
    while queue or i < len(procs):
        if not queue:                       # CPU idle until the next arrival
            time = procs[i][1]
            admit(time)
            continue
        name = queue.popleft()
        run = min(quantum, remaining[name])
        time += run
        remaining[name] -= run
        admit(time)                         # new arrivals go before the preempted job
        if remaining[name] > 0:
            queue.append(name)
        else:
            done[name] = time
    return done


def has_deadlock(wait_for):
    """wait_for: {process: [processes it is waiting for]}. Cycle = deadlock."""
    state = {}                              # 1 = visiting, 2 = finished

    def dfs(p):
        state[p] = 1
        for q in wait_for.get(p, []):
            if state.get(q) == 1 or (q not in state and dfs(q)):
                return True
        state[p] = 2
        return False

    return any(p not in state and dfs(p) for p in list(wait_for))


def safe_sequence(available, maximum, allocation):
    """Banker's algorithm safety check. Returns a safe order or []."""
    need = [[m - a for m, a in zip(mx, al)] for mx, al in zip(maximum, allocation)]
    work, finished, order = available[:], [False] * len(maximum), []
    progress = True
    while progress:
        progress = False
        for i in range(len(maximum)):
            if not finished[i] and all(n <= w for n, w in zip(need[i], work)):
                work = [w + a for w, a in zip(work, allocation[i])]
                finished[i], progress = True, True
                order.append(i)
    return order if all(finished) else []


