def next_term(seq):
    d1 = [b - a for a, b in zip(seq, seq[1:])]
    if len(set(d1)) == 1:                                    # arithmetic
        return seq[-1] + d1[0]
    ratios = [b / a for a, b in zip(seq, seq[1:]) if a]
    if len(ratios) == len(seq) - 1 and len(set(ratios)) == 1:   # geometric
        return int(seq[-1] * ratios[0])
    d2 = [b - a for a, b in zip(d1, d1[1:])]
    if len(set(d2)) == 1:                                    # second-order (squares etc.)
        return seq[-1] + d1[-1] + d2[0]
    return None


def shift_word(word, k):
