        x, y = x + dx * steps, y + dy * steps
    return math.hypot(x, y)


def solve_seating():
    """Row of 5. Ravi at the left end; Meena immediately right of Ravi;
    Kiran not next to Meena; Asha somewhere left of Sam; Sam not at the right end."""
    solutions = []
    for row in permutations(["Ravi", "Meena", "Kiran", "Asha", "Sam"]):
