def star_answer(situation, task, action, result):
    parts = {"situation": situation, "task": task, "action": action, "result": result}
    missing = [name for name, text in parts.items() if not text.strip()]
    if missing:
        raise ValueError(f"missing STAR parts: {missing}")
    return (f"Situation: {situation} Task: {task} "
            f"Action: {action} Result: {result}")


def has_measurable_result(result):
    return any(ch.isdigit() for ch in result)


def tell_me_about_yourself(name, present, past, future):
    return (f"I am {name}. {present} {past} "
            f"{future} That is why this role excites me.")


answer = star_answer(
    "In my semester project our API was slow.",
    "I had to reduce the response time before the demo.",
    "I profiled the code, added an index and cached repeated queries.",
    "Response time dropped from 800 ms to 120 ms and we scored top marks.",
)
assert answer.startswith("Situation:") and has_measurable_result("dropped from 800 ms to 120 ms")
assert not has_measurable_result("It worked well")

try:
