from datetime import date


def weeks_left(today, target):
    return max(0, (target - today).days // 7)


def daily_split(hours, ratios=None):
    ratios = ratios or {"DSA": 55, "Aptitude": 15, "CS core": 10, "English": 10, "Projects": 10}
    minutes = hours * 60
    return {topic: round(minutes * pct / 100) for topic, pct in ratios.items()}


def minimum_mode():
    return {"DSA": 30, "English": 10}               # exam-week plan: never zero


today, target = date(2026, 10, 2), date(2027, 4, 30)
assert weeks_left(today, target) == (target - today).days // 7 > 25
assert weeks_left(target, today) == 0

split = daily_split(3)
assert split == {"DSA": 99, "Aptitude": 27, "CS core": 18, "English": 18, "Projects": 18}
assert sum(split.values()) == 180
assert sum(minimum_mode().values()) == 40
